    public Trade parseTrade(Object trade, Map<String, Object> market)
    {
        //
        // fetchMyTrades
        //
        //     {
        //         "id": "32164924331503616",
        //         "symbol": "LINK_USDT",
        //         "accountType": "SPOT",
        //         "orderId": "32164923987566592",
        //         "side": "SELL",
        //         "type": "MARKET",
        //         "matchRole": "TAKER",
        //         "createTime": 1648635115525,
        //         "price": "11",
        //         "quantity": "0.5",
        //         "amount": "5.5",
        //         "feeCurrency": "USDT",
        //         "feeAmount": "0.007975",
        //         "pageId": "32164924331503616",
        //         "clientOrderId": "myOwnId-321"
        //     }
        //   {
        //     aggregateTradeId: '2659115835',
        //     symbol: 'ETHINR',
        //     price: '292848',
        //     quantity: '0.147',
        //     firstTradeId: '7018766077',
        //     lastTradeId: '7018766081',
        //     tradeTime: '1765381971447',
        //     isBuyerMarketMaker: true
        //   }
        //
        //
        String id = this.safeString2(trade, "id", "aggregateTradeId");
        String orderId = this.safeString2(trade, "id", "order");
        Long timestamp = (Long) this.safeInteger2(trade, "timestamp", "tradeTime");
        String marketId = this.safeString(trade, "symbol");
        Map<String, Object> marketResolved = this.safeMarket(marketId, market, "_", null);
        String symbol = this.safeString(marketResolved, "symbol");
        String side = this.safeStringLower(trade, "side");
        String priceString = this.safeString(trade, "price");
        String amountString = this.safeString2(trade, "amount", "quantity");
        return this.safeTrade(new HashMap<String, Object>() {{
            put( "id", id );
            put( "info", trade );
            put( "timestamp", timestamp );
            put( "datetime", Zebpay.this.iso8601(timestamp) );
            put( "symbol", symbol );
            put( "order", orderId );
            put( "type", Zebpay.this.safeStringLower(trade, "type") );
            put( "side", side );
            put( "takerOrMaker", null );
            put( "price", priceString );
            put( "amount", amountString );
            put( "cost", Zebpay.this.safeString(trade, "cost") );
            put( "fee", Zebpay.this.safeDict(trade, "fee", null) );
        }}, marketResolved);
    }

